style.css:
@-moz-document domain("youtube") {

}

@-moz-document regexp("https?://www.youtube.com?/(?!my_videos|ad_companion|subscribe_embed|account|yt|red).*") {
html,body,ytd-app {
  background-image: url("https://images4.alphacoders.com/706/thumb-1920-706755.png") !important;
  background-size: cover !important;
  background-attachment: fixed !important;
}


html, :root {
  --yt-saturated-raised-background: rgba(219, 35, 198, 0.8) !important;
}


#author-thumbnail-button {
  height : 40px;
  width: 40px ;
  border: 2px solid pink !important;
  border-radius: 20px !important;
}

.ytSpecTouchFeedbackShapeTouchResponse,ytd-playlist-panel-video-renderer,ytd-mini-guide-entry-renderer,#contents-container,#page-header-container,#dismissible,#secondary{
  border: 2px solid pink !important;
  border-radius: 20px !important;
  background-color: rgba(79, 31, 77, 0.5) !important;
}

#above-the-fold,#description,#teaser-carousel,#owner,#comments,#i1,#playlist,#contentContainer  {
    border: 2px solid pink !important;
  border-radius: 10px !important;
  background-color: rgba(0, 91, 92, 0.8) !important;
}


#masthead {
  border: 2px solid #f4bded;
  padding: 0px;
  border-bottom-left-radius: 50px 20px;
  border-bottom-right-radius: 50px 20px;
  background : pink !important
}

#logo-icon svg {
  display: none !important;
}

#logo-icon {
  display: inline-flex !important;
  align-items: center !important;
  gap: 0px !important; 
  width: auto !important;
}

#logo-icon::before {
  content: "" !important;
  display: inline-block !important;
  width: 100px !important;  
  height: 100px !important; 
  background-image: url("https://i.pinimg.com/736x/05/2d/1b/052d1b4f1badbd7a57c0d6374048654b.jpg") !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-size: contain !important;
  margin-right: -50px !important;
}

#logo-icon::after {
  content: "RamTube" !important; 
  font-size: 18px !important;
  font-weight: bold !important;
  font-family: "Roboto", sans-serif !important;
  color: #D55CC2 !important; 
}


#cinematics-container,
#cinematics {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}


  :not([class*="video-extras-sparkbar"])
{
    color: #fca4cd!important;
}

  .load-more-button,#background,#frosted-glass,.ytd-playlist-panel-renderer,.button-container,#guide-content,#page-header,.ytd-tabbed-page-header
  {
    background: transparent!important;
  }

  [role="alert"],.content-region,.yt-uix-checkbox-on-off .checked:before
  {
    display: none!important;
  }

  :not(#​) :link
  {
    color: #ff0077!important;
  }

  :not(#​) :visited
  {
    color: #ff3dbb!important;
  }

  :not(#​) select
  {
    background: black!important;
  }
}

@-moz-document regexp("https://apis.google.com/u/0/_/hovercard.*") {
*
  {
    background-color: #000!important;
    color: #fff!important;
    border-color: #000!important;
  }

  .html5-play-progress, .ytp-play-progress
  {
    background: url("http://i.imgur.com/cmEmClD.png") repeat-x !important;
  }
}
